/* One fixed, fictional football ultimate per species. Never a second move slot. */
(function(root){
'use strict';
const rows=typeof module!=='undefined'?require('./kanto.js'):root.PokeKanto;
const names='Vine Snare|Ivy Surge|Solar Fortress|Ember Dash|Flame Claw|Inferno Wing|Bubble Burst|Shell Surge|Hydro Cannon|Silk Screen|Iron Cocoon|Butterfly Mirage|Poison Needle|Amber Guard|Twin Drill|Gust Step|Sky Cutter|Hurricane Dive|Quick Fang|Super Fang|Feather Blitz|Drill Dive|Coil Trap|Serpent Lock|Thunder Sprint|Voltage Overdrive|Sand Veil|Sandstorm Slash|Venom Spark|Toxic Shield|Royal Rampart|Horn Rush|Venom Horn|Earthbreaker|Moonbeam|Lunar Barrier|Foxfire|Nine-Tail Blaze|Lullaby Feint|Encore Wall|Echo Radar|Night Wing|Root Grip|Spore Cloud|Petal Fortress|Spore Screen|Fungal Wall|Compound Vision|Moth Mirage|Tunnel Burst|Triple Quake|Lucky Swipe|Phantom Pounce|Headache Surge|Psycho Torrent|Rage Rush|Fury Blitz|Flame Charge|Extreme Speed|Spiral Splash|Whirlpool Step|Tidal Grapple|Teleport Step|Mind Bend|Future Sight|Power Chop|Seismic Slam|Four-Arm Fury|Vine Whip|Acid Bloom|Flytrap Lock|Jelly Shield|Kraken Reach|Stone Fist|Rolling Boulder|Mountain Guard|Flame Gallop|Blazing Stampede|Slow Motion|Shell Fortress|Magnet Pulse|Tri-Magnet Radar|Leek Sweep|Twin Step|Triple Threat|Ice Slide|Polar Current|Sludge Screen|Sludge Fortress|Shell Clamp|Icicle Barrage|Mist Walk|Phantom Hands|Shadow Slip|Boulder Coil|Dream Feint|Pendulum Read|Crab Grip|King Claw|Static Burst|Thunder Roll|Seed Barrage|Palm Wall|Bone Guard|Bonemerang|High Jump Kick|Meteor Punch|Tongue Snatch|Smog Screen|Toxic Haze|Horn Charge|Drill Stampede|Lucky Guard|Vine Net|Family Fortress|Bubble Jet|Dragon Current|Horn Stream|Royal Tide|Star Spin|Cosmic Surge|Invisible Wall|X-Scissor|Frozen Kiss|Thunder Punch|Magma Burst|Vice Grip|Raging Stampede|Splash Step|Dragon Rage|Glacier Song|Mirror Form|Adapt Dash|Aqua Mirage|Volt Break|Flare Blitz|Digital Read|Spiral Shell|Ancient Vortex|Fossil Guard|Razor Intercept|Meteor Dive|Giga Impact|Blizzard Wing|Thunderstorm|Phoenix Flight|Dragon Coil|Dragon Veil|Dragon Rush|Psystrike|Genesis Pulse'.split('|');
const colors={grass:'#a3ed80',fire:'#ffad65',water:'#78d9ff',bug:'#cee86c',normal:'#f1deab',poison:'#dc9bff',electric:'#fff075',ground:'#edba80',fairy:'#ffb9e1',fighting:'#ff897c',psychic:'#ff97dd',rock:'#e4ca91',ghost:'#b8a0ff',ice:'#b4f4ff',dragon:'#aba4ff'};
const skills={QB:['Arm','Accuracy','Reads'],WR:['Speed','Hands','Routes','Release'],TE:['Hands','Blocking','Routes'],HB:['Speed','Vision','Carry','Elusiveness'],FB:['Lead block','Carry','Power'],LT:['Pass block','Run block','Footwork'],LG:['Pass block','Run block','Anchor'],C:['Pass block','Run block','Snaps'],RG:['Pass block','Run block','Anchor'],RT:['Pass block','Run block','Footwork'],DE:['Rush','Tackle','Shed'],NT:['Anchor','Tackle','Shed','Rush'],OLB:['Rush','Tackle','Coverage','Shed'],ILB:['Reads','Tackle','Coverage'],CB:['Coverage','Ball skills','Mirror','Tackle'],S:['Reads','Ball skills','Coverage','Tackle']};
const catalog=Object.freeze(rows.map(([id,name,types])=>Object.freeze({id,pokemon:name,name:names[id-1],element:types[0],color:colors[types[0]]})));
function signature(id){const value=catalog[id-1];if(!value||value.id!==id)throw new Error('Unknown ultimate owner');return value}
function boost(p,key){return skills[p.pos]?.includes(key)?12:0}
function description(p){return '+12 '+skills[p.pos].join(' / ')+' for one play (max 99). Auto-triggered once per set of downs.'}
root.PokeUltimates={catalog,signature,boost,description};if(typeof module!=='undefined')module.exports=root.PokeUltimates;
})(typeof window!=='undefined'?window:globalThis);
